 void CenterBarcode(){if(elementMetadata.Exists(m=>m.Index==-1&&m.Locked))return;nums["BarX"].Value=(decimal)Display((N("Width")-N("BarWidth"))/2);preview.SelectElement(-1);timer.Stop();UpdatePreview();}
 void EditElement(ElementEdit edit){if(elementMetadata.Exists(m=>m.Index==edit.Index&&m.Locked)&&!preview.Restoring)return;StoreRotation(edit.Index,edit.Rotation);if(FastMove(edit)||EditSymbolGeometry(edit))return;loading=true;try{if(edit.Index<0){nums["BarX"].Value=(decimal)Display(edit.X);nums["BarY"].Value=(decimal)Display(edit.Y);nums["BarWidth"].Value=(decimal)Display(edit.Width);nums["DigitSize"].Value=(decimal)edit.Font;var settings=Read();double height=Math.Round(Math.Max(1,Math.Min(500,edit.Height-Engine.ExtraHeight(settings,edit.Width,edit.Font))),2);nums["BarHeight"].Value=(decimal)Display(height);}else if(edit.Index<grid.Rows.Count){var row=grid.Rows[edit.Index];row.Cells[1].Value=Display(edit.X);row.Cells[2].Value=Display(edit.Y);row.Cells[3].Value=Display(edit.Width);row.Cells[4].Value=Display(edit.Height);row.Cells[5].Value=edit.Font;}}finally{loading=false;}dirty=true;Text=Loc.T("ND LabelDesigner — Pre-release • neuložené zmeny");timer.Stop();UpdatePreview();}
 static void ComboStyle(ComboBox c){c.FlatStyle=FlatStyle.Flat;c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=24;c.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(var back=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(35,86,134):c.BackColor))e.Graphics.FillRectangle(back,e.Bounds);if(e.Index>=0){TextRenderer.DrawText(e.Graphics,Convert.ToString(c.Items[e.Index]),e.Font,e.Bounds,(e.State&DrawItemState.Selected)!=0?Color.White:c.ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}e.DrawFocusRectangle();};}
 Button Btn(string text,Action action){var b=new ModernButton{Text=text,AutoSize=true,Height=36,Padding=new Padding(8,2,8,2),FlatStyle=FlatStyle.Flat,Margin=new Padding(0,4,8,2)};b.FlatAppearance.BorderColor=Color.LightSteelBlue;b.Click+=delegate{action();};return b;}
 TableLayoutPanel Tab(ModernTabs parent,string name){var tab=parent.AddPage(name);var layout=new TableLayoutPanel{AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Dock=DockStyle.Top,ColumnCount=2,Padding=new Padding(14)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,57));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,43));tab.Controls.Add(layout);return layout;}
 void AddRow(TableLayoutPanel p,string title,Control c){int r=p.RowCount++;p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.Controls.Add(new Label{Text=title,AutoSize=true,Anchor=AnchorStyles.Left,Margin=new Padding(3,9,3,9)},0,r);c.Dock=DockStyle.Fill;c.Margin=new Padding(3,5,3,5);p.Controls.Add(c,1,r);}
 void AddNum(TableLayoutPanel p,string title,string key,decimal min,decimal max,decimal val){var n=new NumericUpDown{Minimum=min,Maximum=max,Value=val,DecimalPlaces=2,Increment=.5m};nums.Add(key,n);AddRow(p,title,n);n.ValueChanged+=Changed;}
 void Changed(object sender,EventArgs args){if(loading)return;dirty=true;Text=Loc.T("ND LabelDesigner — Pre-release • neuložené zmeny");timer.Stop();timer.Start();}
 double N(string key){return (double)nums[key].Value*(Dimension(key)?unitFactor:1);}
 static readonly double[] Dpis={203,203.2,300,304.8,600,609.6};
 LabelSettings Read(){grid.EndEdit();var s=new LabelSettings{Ean=ean.Text,Kind=MoreBarcodes.Kinds[Math.Max(0,kind.SelectedIndex)],Digits=digits.Checked,Sheet=false,Copies=1,UsePaper=paperPreset.SelectedIndex!=0,PaperPreset=PaperOptions.Ids[Math.Max(0,paperPreset.SelectedIndex)],Dpi=Dpis[Math.Max(0,dpi.SelectedIndex)],Unit=unitFactor==10?"cm":"mm",DarkMode=dark,Gs1Mode=gs1Mode.Checked,ApplicationIdentifiers=CopyAi(aiValues),Symbols=CopySymbols(symbols)};foreach(var pair in nums){var field=typeof(LabelSettings).GetField(pair.Key);if(field.FieldType==typeof(int))field.SetValue(s,(int)pair.Value.Value);else field.SetValue(s,N(pair.Key));}
  s.Copies=1;s.Sheet=false;if(!s.UsePaper){s.PageWidth=s.Width;s.PageHeight=s.Height;}
  s.Batch=ProjectXml.Decode<BatchSetup>(ProjectXml.Encode(batchSetup));s.BarRotation=barRotation;s.Metadata=ProjectXml.Decode<List<ElementMeta>>(ProjectXml.Encode(elementMetadata));s.Layout=ProjectXml.Decode<SheetLayout>(ProjectXml.Encode(sheetLayout));s.Variables=ProjectXml.Decode<List<VariableField>>(ProjectXml.Encode(variables));s.HideBarcode=hideBarcode;s.Texts.Clear();foreach(DataGridViewRow row in grid.Rows){var t=new TextItem{Rotation=Convert.ToDouble(row.Tag??0d)};t.Text=Convert.ToString(row.Cells[0].Value)??"";double[] values=new double[5];for(int i=0;i<5;i++)if(!double.TryParse(Convert.ToString(row.Cells[i+1].Value),out values[i]))throw new Exception(Loc.T("Riadok ")+(row.Index+1)+Loc.T(": zadajte číselnú hodnotu pre ")+grid.Columns[i+1].HeaderText+".");t.X=values[0]*unitFactor;t.Y=values[1]*unitFactor;t.Width=values[2]*unitFactor;t.Height=values[3]*unitFactor;t.Size=values[4];t.Bold=Convert.ToBoolean(row.Cells[6].Value??false);t.Center=Convert.ToBoolean(row.Cells[7].Value??false);t.FontName=Convert.ToString(row.Cells[8].Value)??"Arial";s.Texts.Add(t);}return s;
 }
 void Apply(LabelSettings s){loading=true;try{batchSetup=ProjectXml.Decode<BatchSetup>(ProjectXml.Encode(s.Batch??new BatchSetup()));elementMetadata=ProjectXml.Decode<List<ElementMeta>>(ProjectXml.Encode(s.Metadata??new List<ElementMeta>()));sheetLayout=ProjectXml.Decode<SheetLayout>(ProjectXml.Encode(s.Layout??new SheetLayout()));variables=ProjectXml.Decode<List<VariableField>>(ProjectXml.Encode(s.Variables??new List<VariableField>()));hideBarcode=s.HideBarcode;barRotation=s.BarRotation;symbols=CopySymbols(s.Symbols);aiValues=CopyAi(s.ApplicationIdentifiers);gs1Mode.Checked=s.Gs1Mode;SetUnit(s.Unit);dark=s.DarkMode;ean.Text=s.Ean;kind.SelectedIndex=Array.IndexOf(MoreBarcodes.Kinds,s.Kind);digits.Checked=s.Digits;sheet.Checked=s.Sheet;int di=Array.IndexOf(Dpis,s.Dpi);if(di<0)throw new Exception(Loc.T("Súbor obsahuje nepodporované DPI."));dpi.SelectedIndex=di;foreach(var pair in nums)pair.Value.Value=Convert.ToDecimal(typeof(LabelSettings).GetField(pair.Key).GetValue(s))/(decimal)(Dimension(pair.Key)?unitFactor:1);grid.Rows.Clear();foreach(var t in s.Texts){EnsureFont(t.FontName);int row=grid.Rows.Add(t.Text,Display(t.X),Display(t.Y),Display(t.Width),Display(t.Height),t.Size,t.Bold,t.Center,t.FontName);grid.Rows[row].Tag=t.Rotation;}LoadPaper(s);Gs1State();ApplyTheme();}finally{loading=false;}dirty=false;Text="ND LabelDesigner — Pre-release";preview.SelectElement(-1);UpdatePreview();}
 void AddText(){if(grid.Rows.Count>=50)return;grid.Rows.Add(Loc.T("Nový text"),Display(3),Display(3),Display(Math.Max(1,N("Width")-6)),Display(6),10,false,false,"Arial");Changed(this,EventArgs.Empty);timer.Stop();UpdatePreview();preview.SelectElement(grid.Rows.Count-1);}
 void RemoveText(){if(history!=null){RemoveSelected();return;}if(preview.SelectedIndex<=-3){int i=-3-preview.SelectedIndex;if(i<symbols.Count)symbols.RemoveAt(i);preview.SelectElement(-1);Changed(this,EventArgs.Empty);timer.Stop();UpdatePreview();return;}if(grid.CurrentCell!=null){grid.Rows.RemoveAt(grid.CurrentCell.RowIndex);preview.SelectElement(-1);Changed(this,EventArgs.Empty);}}
 bool CanDiscard(){if(!dirty)return true;var r=UiMessageBox.Show(this,Loc.T("Chcete uložiť aktuálne nastavenie etikety?"),Loc.T("Neuložené nastavenie"),MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(r==DialogResult.Cancel)return false;if(r==DialogResult.Yes){Save();return !dirty;}return true;}
 void Open(){if(!CanDiscard())return;using(var d=new OpenFileDialog{Filter=Loc.T("Podporované súbory (*.ean.xml;*.xml;*.zpl;*.prn)|*.ean.xml;*.xml;*.zpl;*.prn|Nastavenie etikety (*.ean.xml)|*.ean.xml|ZPL / PRN (*.zpl;*.prn)|*.zpl;*.prn|XML (*.xml)|*.xml")})if(d.ShowDialog(this)==DialogResult.OK)try{OpenImportedFile(d.FileName);}catch(Exception ex){Error(ex);}}
 void SaveDocument(string path){CommitInspectorIfFocused();var s=Read();Engine.Save(path,s);settingsPath=path;dirty=false;Text="ND LabelDesigner — Pre-release";UpdatePreview();DocumentSaved();status.Text=(labelIssues.Exists(i=>i.Blocking)?Loc.T("Koncept uložený")+": ":Loc.T("Nastavenie uložené: "))+settingsPath;}
 void Save(){if(settingsPath==null){SaveAs();return;}try{SaveDocument(settingsPath);}catch(Exception ex){Error(ex);}}
 void SaveAs(){using(var d=new SaveFileDialog{Filter=Loc.T("Nastavenie etikety (*.ean.xml)|*.ean.xml"),FileName=Loc.T("Moja etiketa.ean.xml")})if(d.ShowDialog(this)==DialogResult.OK)try{SaveDocument(d.FileName);}catch(Exception ex){Error(ex);}}
 static void Atomic(string target,Action<string> action){string tmp=target+"."+Guid.NewGuid().ToString("N")+".tmp";try{action(tmp);if(File.Exists(target))File.Replace(tmp,target,null,true);else File.Move(tmp,target);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 void Export(string format){try{var job=new PreparedLabelJob(Read(),currentTime());var s=job.Label;if(s.Layout.Enabled){ExportJob(job.Plan,s.Dpi,format);return;}Engine.Validate(s);var warnings=LabelChecks.Inspect(s).ConvertAll(i=>i.ToString());if(warnings.Count>0&&UiMessageBox.Show(this,string.Join("\r\n",warnings.ToArray())+Loc.T("\r\n\r\nPokračovať v exporte?"),Loc.T("Kontrola etikety"),MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;using(var d=new SaveFileDialog{Filter=format.ToUpper()+" (*."+format+")|*."+format,FileName="ND-LabelDesigner-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+"."+format})if(d.ShowDialog(this)==DialogResult.OK){UseWaitCursor=true;try{Atomic(d.FileName,delegate(string p){if(format=="pdf")Engine.Pdf(p,s);else if(format=="docx")Engine.Docx(p,s);else if(format=="svg")Engine.Svg(p,s);else Engine.Zpl(p,s);});status.Text=Loc.T("Export uložený: ")+d.FileName;status.ForeColor=Color.FromArgb(32,84,58);}finally{UseWaitCursor=false;}}}catch(Exception ex){Error(ex);}}
 void Error(Exception e){UiMessageBox.Show(this,e.Message,"ND LabelDesigner — Pre-release",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 void Help(){UiMessageBox.Show(this,Loc.T("Otáčanie: kruhový úchyt nad prvkom. Pri uhloch 0°, 90°, 180° a 270° sa prvok prichytí v tolerancii 3°. Shift prichytáva po 15°. Esc zruší rozpracovanú zmenu. Uhol zadáte aj vo vlastnostiach alebo cez pravé tlačidlo myši. Ctrl+] a Ctrl+[ otáčajú o 90°.")+"\r\n\r\n"+Loc.T("Nastavte rozmery etikety a údaje kódu. Prvky presúvajte myšou, veľkosť meňte úchytmi a text upravte dvojklikom.\r\n\r\nNa karte Papier a kópie vyberte bežný formát, Podľa etikety alebo Vlastné rozmery. Pre papier nastavte všetky štyri okraje. Na každej strane je jedna etiketa.\r\n\r\nTlačiť otvorí samostatné tlačové okno. Vyberte tlačiareň a počet kópií, skontrolujte náhľad a kliknite na Tlačiť. Vlastnosti tlačiarne sú pod Rozšírené nastavenia. Späť do editora alebo Esc obnoví rozpracovaný návrh. Zoom mení iba náhľad; tlačí sa v skutočnej veľkosti.\r\n\r\nWord obsahuje samostatné transparentné SVG objekty: každý text, celý čiarový kód s popisom a každý symbol. Objekty môžete vo Worde presúvať a meniť ich veľkosť; obsah textu upravujte v tomto programe. SVG export celej etikety zostáva transparentný.\r\n\r\nNastavenia spustenia ukladajú iba jazyk, vzhľad, jednotky a rozmery etikety. Projekty ukladajte cez Uložiť / Uložiť ako. GS1 nastavíte cez Code 128 a Identifikátory. ZPL/PRN majú obmedzený import."),Loc.T("Ako používať program"),MessageBoxButtons.OK,MessageBoxIcon.Information);}
 public void CapturePreview(string path){Size=new Size(1320,930);Show();Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path);}dirty=false;Close();}
}
public static class Program {
 [STAThread]public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length==2&&args[0]=="--self-test"){try{SelfTest(args[1]);Environment.ExitCode=0;}catch(Exception ex){Directory.CreateDirectory(args[1]);File.WriteAllText(Path.Combine(args[1],"failure.txt"),ex.ToString());Environment.ExitCode=1;}return;}Application.Run(new MainForm());}
 static void Assert(bool val,string what){if(!val)throw new Exception("Test zlyhal: "+what);}
 static void Reject(Action a,string what){bool rejected=false;try{a();}catch{rejected=true;}Assert(rejected,what);}
 static void SelfTest(string folder){Directory.CreateDirectory(folder);Assert(Engine.Normalize("400638133393",13)=="4006381333931","EAN13 checksum");Assert(Engine.Normalize("9638507",8)=="96385074","EAN8 checksum");Assert(Engine.Normalize("000000000000",13)=="0000000000000","leading zeros");Reject(delegate{Engine.Normalize("4006381333932",13);},"wrong checksum");Reject(delegate{Engine.Normalize("123A567",8);},"letters");Reject(delegate{Engine.Normalize("１２３４５６７",8);},"unicode digits");Assert(Engine.Bits("4006381333931",13).Length==95,"95 modules");Assert(Engine.Bits("96385074",8).Length==67,"67 modules");var s=LabelSettings.Default();Assert(Engine.Normalize(s.Ean,13)==s.Ean,"default valid");
  foreach(int k in new[]{13,8}){s.Kind=k;s.Ean=k==13?"4006381333931":"96385074";using(var b=Engine.Render(s))b.Save(Path.Combine(folder,"ean"+k+".png"));Engine.Pdf(Path.Combine(folder,"ean"+k+".pdf"),s);Engine.Docx(Path.Combine(folder,"ean"+k+".docx"),s);Engine.Zpl(Path.Combine(folder,"ean"+k+".zpl"),s);}
  s.Kind=13;s.Ean="4006381333931";s.Sheet=true;s.Copies=25;Assert(Engine.Columns(s)==3&&Engine.Rows(s)==5,"A4 grid");Engine.Pdf(Path.Combine(folder,"sheet.pdf"),s);Engine.Docx(Path.Combine(folder,"sheet.docx"),s);Engine.Save(Path.Combine(folder,"settings.ean.xml"),s);Assert(Engine.Load(Path.Combine(folder,"settings.ean.xml")).Copies==25,"settings roundtrip");s.Width=10;Engine.Validate(s);Assert(Engine.Warnings(s).Count>0,"overflow warning");s=LabelSettings.Default();s.Dpi=203.2;Engine.Zpl(Path.Combine(folder,"203dpi.zpl"),s);using(var b=Engine.Render(s)){Assert(b.Width==480&&b.Height==360,"8dots per mm");}
  s=LabelSettings.Default();s.Width=210;s.Height=100;s.Dpi=600;Engine.Zpl(Path.Combine(folder,"large.zpl"),s);using(var b=Engine.Render(s))b.Save(Path.Combine(folder,"large.png"));
  using(var form=new MainForm(Path.Combine(folder,"self-test-startup.xml")))form.CapturePreview(Path.Combine(folder,"app.png"));File.WriteAllText(Path.Combine(folder,"passed.txt"),"EAN checksum, leading zeros, invalid data, module lengths, label boundaries, A4 pagination, XML roundtrip, PDF/DOCX/ZPL generation and UI rendering passed.");
 }
